from __future__ import print_function
import sys, os, zipfile, re, shutil
from collections import Counter
from openpyxl import load_workbook

zip_path = sys.argv[1]
work = 'workbooks'
if os.path.exists(work):
    shutil.rmtree(work)
os.makedirs(work)
with zipfile.ZipFile(zip_path) as z:
    z.extractall(work)

def norm_id(x):
    if x is None:
        return ''
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    if isinstance(x, int):
        return str(x)
    s = str(x).strip()
    if re.match(r'^\d+\.0$', s):
        s = s[:-2]
    return s

def norm_text(x):
    if x is None:
        return ''
    return str(x).strip()

def truthy(x):
    return norm_text(x).lower() in ('true','yes','1','y')

def to_float(x):
    if x is None:
        return None
    if isinstance(x, (int, float)):
        return float(x)
    s = str(x).strip()
    if not s:
        return None
    try:
        return float(s)
    except Exception:
        return None

def find_file(ending):
    matches = []
    for root, dirs, files in os.walk(work):
        for name in files:
            if name == ending:
                matches.append(os.path.join(root, name))
    if len(matches) != 1:
        raise RuntimeError('Expected one file named %s, found %d' % (ending, len(matches)))
    return matches[0]

status_path = find_file('230215_Trio_Status.xlsx')
chip_path = find_file('230214_Schenz_et_al_2022_CHIP_Genes.xlsx')

wb = load_workbook(status_path, read_only=False, data_only=True)
ws = wb.active
rows = list(ws.iter_rows(values_only=True))
headers = [norm_text(v) for v in rows[0]]
hidx = dict((h, i) for i, h in enumerate(headers) if h)
sample_status = {}
for row in rows[1:]:
    sid = norm_id(row[hidx['Sample ID']])
    blm = norm_text(row[hidx['BLM Mutation Status']])
    if sid:
        sample_status[sid] = blm

wb = load_workbook(chip_path, read_only=False, data_only=True)
ws = wb.active
chip_genes = set()
for row in ws.iter_rows(values_only=True):
    if row and row[0] is not None:
        chip_genes.add(norm_text(row[0]).upper())

variant_files = []
for root, dirs, files in os.walk(work):
    for name in files:
        if name.endswith('.xlsx') and 'CHIP_DP10_GQ20_PASS' in root:
            variant_files.append(os.path.join(root, name))
variant_files.sort()

needed = ['Chr:Pos','Ref/Alt','Zygosity','Variant Allele Freq','Gene Names','Sequence Ontology (Combined)','Classification','In_CHIP']
records = []
class_counts = Counter()
carrier_files = 0
skipped_noncarrier = 0

for path in variant_files:
    base = os.path.basename(path)
    m = re.match(r'230209_Exome_GRCh38_CHIP_(.+)\.xlsx$', base)
    if not m:
        continue
    token = m.group(1)
    if token.startswith('SRR'):
        sid = token.strip()
    else:
        sid = token.split('-')[0].strip()
    if sample_status.get(sid) != 'Carrier':
        skipped_noncarrier += 1
        continue
    carrier_files += 1
    wb = load_workbook(path, read_only=False, data_only=True)
    ws = wb.active
    header_row = None
    for row in ws.iter_rows(values_only=True):
        vals = [norm_text(v) for v in row]
        if 'Chr:Pos' in vals and 'Classification' in vals and 'Variant Allele Freq' in vals:
            header_row = vals
            break
    if header_row is None:
        raise RuntimeError('No variant header found in %s' % base)
    idx = dict((h, i) for i, h in enumerate(header_row) if h)
    for n in needed:
        if n not in idx:
            raise RuntimeError('Missing column %s in %s' % (n, base))
    start = False
    for row in ws.iter_rows(values_only=True):
        vals = [norm_text(v) for v in row]
        if not start:
            if vals == header_row:
                start = True
            continue
        zyg = norm_text(row[idx['Zygosity']])
        if zyg.lower() == 'reference' or zyg == '':
            continue
        vaf = to_float(row[idx['Variant Allele Freq']])
        if vaf is None or not (vaf < 0.3):
            continue
        so = norm_text(row[idx['Sequence Ontology (Combined)']])
        so_l = so.lower()
        if ('intron' in so_l) or ('intergenic' in so_l) or ('utr' in so_l):
            continue
        genes_text = norm_text(row[idx['Gene Names']])
        genes = set(g.upper() for g in re.split(r'[;,\s]+', genes_text) if g)
        in_chip = truthy(row[idx['In_CHIP']]) or bool(genes & chip_genes)
        if not in_chip:
            continue
        classification = norm_text(row[idx['Classification']])
        if classification == '' or classification.lower() in ('none','nan','na','n/a'):
            continue
        is_blb = classification.lower() in ('benign','likely benign')
        class_counts[classification] += 1
        records.append((sid, base, norm_text(row[idx['Chr:Pos']]), norm_text(row[idx['Ref/Alt']]), zyg, vaf, genes_text, so, classification, '1' if is_blb else '0'))

den = len(records)
num = sum(1 for r in records if r[-1] == '1')
if den == 0:
    prop = 'nan'
else:
    prop = ('%.17g' % (float(num) / float(den)))

with open('answer.txt','w') as out:
    out.write(prop + '\n')
with open('audit.tsv','w') as out:
    out.write('metric\tvalue\n')
    out.write('carrier_files\t%d\n' % carrier_files)
    out.write('skipped_noncarrier_files\t%d\n' % skipped_noncarrier)
    out.write('denominator_clinvar_somatic_chip_variants\t%d\n' % den)
    out.write('numerator_benign_or_likely_benign\t%d\n' % num)
    out.write('proportion\t%s\n' % prop)
    for cls, count in sorted(class_counts.items()):
        out.write('classification:%s\t%d\n' % (cls, count))
with open('filtered_variants.tsv','w') as out:
    out.write('sample_id\tfile\tchr_pos\tref_alt\tzygosity\tvaf\tgene_names\tsequence_ontology\tclassification\tbenign_or_likely_benign\n')
    for rec in records:
        out.write('\t'.join(str(x) for x in rec) + '\n')
